const buttons=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.card')],input=document.querySelector('#search'),shell=document.querySelector('#search-form'),conditions=document.querySelector('#search-conditions');let category='all';const normalize=text=>text.toLowerCase().replace(/\s+/g,'').replace(/캐틀벨/g,'케틀벨').replace(/덤벨/g,'아령');const aliases={bedding:'침구 이불 차렵이불 침대',fitness:'홈트 운동 헬스 근력',food:'식품 과일 감귤 귤 간식',household:'생활용품 세제 세탁 빨래 분말세제 리필'};function updateResults(){const terms=input.value.toLowerCase().trim().split(/\s+/).filter(Boolean).map(normalize);let count=0;cards.forEach(card=>{if(card.dataset.pinned==='true'){card.hidden=false;count++;return;}const text=normalize(card.textContent+' '+(aliases[card.dataset.category]||''));card.hidden=(category!=='all'&&card.dataset.category!==category)||!terms.every(term=>text.includes(term));if(!card.hidden)count++});document.querySelector('.count').textContent=count+'개';document.querySelector('.empty-state').hidden=count!==cards.filter(card=>card.dataset.pinned==='true').length;}buttons.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));updateResults()}));function setConditionsOpen(expanded){input.setAttribute('aria-expanded',String(expanded));conditions.hidden=!expanded;}
input.addEventListener('input',()=>{setConditionsOpen(true);updateResults()});
input.addEventListener('focus',()=>setConditionsOpen(true));
input.addEventListener('click',()=>setConditionsOpen(true));
shell.addEventListener('submit',event=>{event.preventDefault();updateResults();setConditionsOpen(false);input.blur()});
document.addEventListener('pointerdown',event=>{if(!shell.contains(event.target))setConditionsOpen(false)});
shell.addEventListener('focusout',event=>{if(!shell.contains(event.relatedTarget))setConditionsOpen(false)});
shell.addEventListener('keydown',event=>{if(event.key==='Escape'){setConditionsOpen(false);input.blur()}});
document.querySelector('#reset-search').addEventListener('click',()=>{input.value='';category='all';buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));updateResults();input.focus()});